slide.example:
variable:
        *T_VARIABLE*           { $$ = zend_ast_create(*ZEND_AST_VAR*, $1); }
scalar:
        |0000cc|T_LNUMBER|            { $$ = $1; }
expr:
    |   variable |00cc00|'='| expr    { $$ = zend_ast_create(|00cc00|ZEND_AST_ASSIGN|, $1, $3); }
    |   expr |cc00cc|'+'| expr        { $$ = zend_ast_create_binary_op(|cc00cc|ZEND_ADD|, $1, $3); }
    |   scalar { $$ = $1; }
